"""Build the public, static progress-check page from the same aggregate evidence."""
from html import escape as e
import json
from pathlib import Path
from render_site import render_page
from midterm_sections import sections as midterm_sections
from platform_sections import sections as platform_sections

ROOT=Path(__file__).resolve().parents[1]
d=json.loads((ROOT/'data/summary.json').read_text())
def table(headers,rows,caption):
    return '<div class="table-scroll"><table><caption>'+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def figure(name,alt,caption):
    figure_class = ' class="score-detail"' if name == '03-score-progression' else ''
    return f'<figure{figure_class}><picture><source media="(max-width: 900px)" srcset="assets/figures/{name}-mobile.svg"><img src="assets/figures/{name}.svg" alt="{e(alt)}" loading="lazy"></picture><figcaption>{caption}</figcaption></figure><div class="downloads"><a href="assets/figures/{name}.png" download>Download PNG ↗</a><a href="assets/figures/{name}.svg" download>Download SVG ↗</a><a href="assets/figures/{name}.pdf" download>Download PDF ↗</a></div>'
counts=table(['Homework','Problems','Submitters','Submissions','Minimum','Q1','Median','Q3','Maximum'],[[a['homework'],a['problems'],a['all_attempts']['n'],a['submissions'],*[f"{a['all_attempts'][k]:g}" for k in ['min','q1','median','q3','max']]] for a in d['assignments']], 'Window-based attempt counts; one observation per student and homework with ≥1 submission.')
score_rows=sorted(d['score_progression'], key=lambda r: -(r['best']-r['best3']))
scoretable=table(['Homework','Problem','Name','Attempters','First mean','Best through 2','Best through 3','Best observed','Remaining gap after 3 (pp)'],[[r['homework'],f"P{r['problem_order']}",r['problem_name'],r['n'],f"{r['first']:.2f}",f"{r['best2']:.2f}",f"{r['best3']:.2f}",f"{r['best']:.2f}",f"{r['best']-r['best3']:.2f}"] for r in score_rows],'Per-problem mean normalized scores for the same attempters, sorted by best observed minus best through three. Intermediate columns are cumulative best through two or three attempts.')
late_gain_problems=sum(r['best']-r['best3'] > 10 for r in score_rows)
caltable=table(['Date','Hours (Beijing)','Status','Submissions','Distinct contributors'],[[c['date'],f"{c['hour']:02d}:00–{c['hour']+4:02d}:00",c['state'],c['submissions'] if c['submissions'] is not None else '—',c['contributors'] if c['contributors'] is not None else '—'] for c in d['calendar']], 'Public four-hour calendar cells. Suppressed cells have 1–4 contributors. Inactive cells have no configured homework window.')
windows=table(['Homework','Opens (UTC+08)','Configured deadline (UTC+08)','Outside-window records'],[[a['homework'],a['start_local'][:16].replace('T',' '),a['end_local'][:16].replace('T',' '),a['outside_window']] for a in d['assignments']], 'Configured assignment windows. Individual extensions have not been incorporated.')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Four actual-data visualizations of CS201 homework submission timing, retries, and score progression."><title>CS201 Homework Submission Patterns</title><link rel="stylesheet" href="styles.css"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"></head><body><a class="skip" href="#main">Skip to content</a><header class="site-header"><a class="brand" href="#">CS201 / PROCESS NOTES</a><nav aria-label="Main navigation"><a href="#timing">Figures</a><a href="#dataset">Dataset</a><a href="#evaluation">Evaluation</a></nav></header><main id="main"><section class="hero"><p class="eyebrow">STATS 401 · FINAL PROJECT · IN-CLASS PROGRESS CHECK</p><h1>Similar scores.<br><em>Different paths.</em></h1><p class="lead">CS201 Homework Submission Patterns:<br>Timing, Retries, and Score Progression</p><p class="intro">When homework scores cluster near full marks, the submission process still varies. We examine when students submit, how often they retry, and how first scores compare with the best scores they reach.</p><p class="byline">Zaozao Wang &amp; Zhengxiang Liu · Snapshot: 20 September 2026</p><div class="stats"><div><strong>2,101</strong><span>submissions within homework windows</span></div><div><strong>39 / 42</strong><span>roster members with window submissions</span></div><div><strong>3</strong><span>homeworks · 23 problem slots</span></div></div><p class="status">Current milestone: four implemented static figures using actual project data. Interactions and the user evaluation below are planned.</p></section>
<section class="opening" id="research-question"><p class="eyebrow">THE QUESTION</p><h2>What do near-perfect scores leave out?</h2><p>In the <code>participation_mode=0</code> records, 37/40 HW1 scores, 33/39 HW2 scores and 37/39 HW3 scores are 100. The formal interpretation of this participation field still needs confirmation. These records motivate a process-focused analysis; they are not a substitute for verifying the official grading rules.</p><p>Within the observation windows, <strong>178 submissions earned partial credit</strong>. The figures below describe that recorded process. Submission gaps are not measured study time, and more attempts do not establish greater effort or better learning.</p></section>
<section class="chart-section" id="timing"><div class="section-heading"><span class="number">01</span><div><p class="eyebrow">TIMING / VISIBLE CELLS</p><h2>When does a burst reflect<br>broad participation?</h2></div></div><p class="reading">Across the full day on <strong>29 August, 233 submissions came from 14 students</strong>. The busiest <em>publicly visible</em> four-hour cell is 12:00–16:00 that day: 153 submissions from 12 students, or 12.75 submissions per active contributor. It was a Saturday before HW1's configured deadline. This identifies a submission burst, not study time.</p>'''
html+=figure('01-calendar','Two panels plot publicly visible positive four-hour cells. Reach versus submissions per active contributor, and Beijing clock time versus submissions. The largest visible cell is August 29, 12 to 16, with 153 submissions from 12 contributors.','Marker shape identifies homework and marker area scales with submission count. Only 29 positive cells with at least five contributors appear. The other 51 positive cells contain 677 submissions but are masked, so the true busiest four-hour cell cannot be established from this public figure. Ratios do not describe every student equally.')
html+='<details><summary>Accessible data table · calendar</summary>'+caltable+'</details><div class="plan"><h3>Next analysis when event data are available</h3><p>Recalculate activity relative to each homework deadline and compare time-of-day patterns after accounting for how long each interval was open. Review any public aggregation for sparse-cell disclosure before replacing this visible-cell figure. Submission time is not a measure of study duration.</p></div></section>'
html+='''<section class="chart-section" id="retries"><div class="section-heading"><span class="number">02</span><div><p class="eyebrow">RETRIES</p><h2>A typical count hides a wide range.</h2></div></div><p class="reading">Median counts are <strong>12.5, 13 and 14</strong>, but observed ranges are 8–98, 3–62 and 7–108. The distributions include only students who submitted within each homework window. The underlying tasks also differ: HW1 and HW2 have eight problems; HW3 has seven.</p>'''
html+=figure('02-attempts','Three boxplots of student submission counts. HW1 median 12.5 and range 8–98; HW2 median 13 and range 3–62; HW3 median 14 and range 7–108.','Whiskers show the observed minimum and maximum, not 1.5×IQR. Boxes use inclusive quartiles. No individual student points are published. Different problem counts and difficulty limit comparisons across homeworks.')
html+='<details><summary>Accessible data table · attempt counts</summary>'+counts+'</details><div class="plan"><h3>Planned interaction / animation</h3><p>Switch between all attempts and attempts through the first accepted submission for each student–problem pair, including that successful attempt. Retain all observed attempts for pairs that never reach acceptance. Animate the box transition briefly, with a reduced-motion option, to show how <strong>318 post-acceptance submissions</strong> affect the distributions. Acceptance uses the recorded AC verdict; it is distinct from normalized full score.</p></div></section>'
html+=f'''<section class="chart-section" id="scores"><div class="section-heading"><span class="number">03</span><div><p class="eyebrow">PROBLEM BOTTLENECKS</p><h2>Which problems remain difficult<br>after three attempts?</h2></div></div><p class="reading">The chart ranks problem slots by the gap between mean best observed and mean best through three attempts. <strong>HW3 EvenOrOdd</strong> has the largest remaining gap: 66.15 through three versus 100 eventually, a 33.85-point difference among the same 39 attempters. That makes it a candidate for reviewing the task statement and feedback, not proof of a defective problem.</p><p>For <strong>{late_gain_problems} of 23 problem slots</strong>, this remaining gap exceeds 10 percentage points. The red segment shows that gap; the lighter segment places it beside the first-submission mean. These are problem-level means, not the number of students who improved.</p>'''
html+=figure('03-score-progression','Ranked problem score paths show first submission, best through three attempts, and best observed. The red segment marks the remaining mean gap after three attempts. Nine of 23 problem slots have a gap above ten points.','Scores are normalized within each homework problem, with the same attempters at all three stages, including one-attempt pairs. Best through three is a cumulative maximum, not the actual third score. The gap helps prioritize questions for review but does not identify its cause or establish a learning effect. Exact values, including best through two, appear in the table.')
html+='<details><summary>Accessible data table · four score stages</summary>'+scoretable+'</details><div class="plan"><h3>Next analysis when event data are available</h3><p>Calculate, by problem and attempt number, the share of eligible repeats that set a new personal best or first reach acceptance. The current problem-level mean gaps cannot tell us how many students improved or why a particular problem remained difficult.</p></div></section>'

attempttable=table(['Homework','Attempt','Mean actual score (%)','Submission events (N)','Distinct students (S)'],
    [[r['homework'],r['attempt'],f"{r['mean_score']:.2f}",r['submissions'],r['contributors']]
     for r in d['attempt_score_series'] if r['state']=='visible'],
    'Each point includes only pairs reaching that attempt. Fewer than five students: point withheld; no score carried forward.')
html+='''<section class="chart-section" id="attempt-scores"><div class="section-heading"><span class="number">04</span><div><p class="eyebrow">MEAN SCORE BY ATTEMPT</p><h2>What does each successive<br>submission actually score?</h2></div></div><p class="reading">Each point averages the <strong>actual score on the nth submission to the same homework problem</strong>, normalized to 0–100. HW1, HW2 and HW3 are separate panels. This is not a running-best curve.</p><p>For HW1, the first-attempt mean is 76.93 across 304 student–problem events from 38 students; the second-attempt mean is 64.53 across 106 events from 34 students. Students who finish a problem and stop submitting no longer contribute to its later points. <strong>A lower later mean does not mean the same group became worse.</strong></p>'''
html+=figure('04-attempt-scores','Three panels show mean actual normalized score at each within-problem attempt number. Sample sizes decrease as fewer student–problem pairs continue submitting.','N counts submitted student–problem events; S counts distinct students. All observed attempts are eligible, including post-acceptance attempts. Each event has equal weight, so a student retrying several problems contributes several events. Points with fewer than five students are withheld; gray tails indicate withheld positions within the displayed range. There are no carried-forward values, confidence bands or claims of causality.')
html+='<details><summary>Accessible data table · actual score by attempt</summary>'+attempttable+'</details><div class="plan"><h3>Planned interaction / animation</h3><p>Filter by problem or homework, inspect mean/N/S on hover, and compare actual-attempt scores with cumulative-best summaries under explicitly different cohort definitions. Keep sample counts visible during transitions and apply the minimum-contributor rule after filtering. The purpose is to expose changing sample composition, not imply individual learning trajectories.</p></div></section>'

html+='''<section id="dataset" class="methods"><p class="eyebrow">DATASET &amp; PROCESSING</p><h2>From private event logs<br>to reproducible summaries.</h2><div class="two-col"><div><h3>Raw dataset · private</h3><p>A read-only CS201 course export contains nine tables: metadata, course, roster, assignments, submissions, assignment–problem mappings, problems, participations and submission–assignment links. The scoped export contains 42 non-staff/non-superuser roster members and 2,343 submission events from 40 members, across seven assignments. It excludes source code and direct identity fields from the analysis bundle. Pseudonyms remain private.</p><p>The export is a snapshot, not a live connection. The website never queries the production server. Raw logs, individual scores and the linkage key are not published.</p></div><div><h3>Processed dataset · public</h3><p>The three homework assignments contain 2,171 submission events. Restricting each event to its own configured homework opening and deadline retains <strong>2,101 events from 39 students</strong>; 70 events outside these windows remain in the raw export but are excluded from these figures.</p><p>The published <a href="data/summary.json">aggregate JSON</a> contains masked time bins, homework count distributions and per-problem score means. It contains no student identifiers or event-level records. Public bins require at least five contributors; suppression reduces disclosure but is not a formal privacy guarantee.</p></div></div><h3>Completed processing</h3><ol><li>Confirmed the CS201 roster scope, removed staff/superuser accounts, and recorded the original account scope. A test account identified on 21 September is excluded from the new midterm cohort; the original snapshot denominator is retained and explicitly labeled.</li><li>Checked unique keys and join coverage for submissions, assignment links and problem maxima. Repeated attempts remain separate events; they are not treated as accidental duplicates.</li><li>Converted UTC timestamps to Asia/Shanghai before assigning dates or time bins; selected the configured homework windows below.</li><li>Validated finite scores and positive maxima, then calculated <code>100 × assignment_submission_score / problem_max_points</code>. Raw cross-problem scores are not mixed.</li><li>Sorted student–homework–problem events by timestamp and submission ID, computed first and running-best scores, and aggregated over the same attempters.</li><li>Created summary boxplots and masked calendar bins. Zero-submitters remain in the roster count but are excluded from attempt-count distributions.</li></ol>'''+windows+'''<p class="caution">Scope limitations: configured deadlines may differ from individual extensions. These are recorded submissions, not all work a student performed. The original homework figures use the 20 September snapshot. The midterm extension uses a separately verified, partial cohort; Course Pulse usage is analyzed separately in chapters 08–10; no causal claims are made.</p><p><a href="docs/methods.md">Detailed methods and data dictionary ↗</a> · <a href="https://github.com/Cis-jujube/STATS-401-Final-Project">Source and reproduction instructions ↗</a></p></section>
<section id="evaluation" class="evaluation"><p class="eyebrow">EVALUATION PLAN · NOT YET RUN</p><h2>Can readers answer the questions<br>without overinterpreting the data?</h2><p>We plan a formative study with approximately five classmates or teaching assistants. Participants will use the static page first, then repeat comparable tasks after interactions are implemented. We will rotate task order, use think-aloud observation, and avoid treating this small convenience sample as a representative experiment.</p><div class="table-scroll"><table><caption>Tasks, evaluation criteria and feedback to collect</caption><thead><tr><th scope="col">Task</th><th scope="col">What we evaluate</th><th scope="col">What we collect</th></tr></thead><tbody><tr><td>Find a visible submission peak and compare its two panels.</td><td>Reading marker positions and sizes, counts versus distinct people, and masked cells.</td><td>Answer correctness, completion time, help requests and misread cells.</td></tr><tr><td>Compare the medians and ranges of the three homeworks.</td><td>Understanding boxes, min–max whiskers, denominators and unequal problem counts.</td><td>Correctness, time, confidence (1–5), and confusing labels.</td></tr><tr><td>Identify the largest remaining mean score gap after three attempts.</td><td>Reading best-through-three versus best-observed scores and the same-cohort comparison.</td><td>Selected problem, estimated remaining gap, time and explanation.</td></tr><tr><td>Read the first and second attempt means and their N/S rows.</td><td>Distinguishing actual-attempt scores from running best and recognizing cohort attrition.</td><td>Correctness, time and explanation of why a falling mean need not indicate individual decline.</td></tr><tr><td>Explain what more attempts and longer submission gaps can tell us.</td><td>Whether the page prevents effort, study-time and causal-learning misconceptions.</td><td>Open-ended explanation, misconception notes and wording suggestions.</td></tr></tbody></table></div><p>The current aggregate-derived answer key is documented in the evaluation plan. We will summarize task accuracy, median completion time and repeated points of confusion, then revise labels, legends and interaction defaults. Feedback will be recorded without names; no evaluation results are claimed at this milestone.</p></section>
<section class="next" id="retry-intervals"><p class="eyebrow">FUTURE EXTENSION / RETRY INTERVALS</p><h2>Does the next attempt set a new best?</h2><p>Explore adjacent submissions within the same student, homework and problem, restricted to cases where the prior best is below full credit and a next attempt is observed. Compare the proportion exceeding the historical best across retry-gap bins, reporting both pair counts and distinct contributors.</p><p>Stratify by problem, prior score and prior verdict. Sparse bins will be combined or withheld. Any uncertainty estimates must account for repeated observations within students. A retry gap is elapsed clock time, not study duration; this remains an exploratory association. This retry-interval analysis is separate from the ten completed static visualizations.</p></section></main><footer><p>CS201 Homework Submission Patterns · Zaozao Wang &amp; Zhengxiang Liu</p><p>Actual project data · Static progress check · 20 Sep 2026</p><p>Figure style follows <a href="https://github.com/ChenLiu-1996/figures4papers/tree/main/scientific-figure-making">figures4papers / Scientific Figure Making</a>; generated with Matplotlib.</p><a href="proposal.md">Original proposal (historical, superseded scope)</a></footer></body></html>'''
# Add the new evidence without changing the original homework figures.
midterm = json.loads((ROOT/'data/midterm-summary.json').read_text())
html = html.replace('</main>', midterm_sections(midterm, table, figure) + '</main>')
platform = json.loads((ROOT/'data/platform-summary.json').read_text())
html = html.replace('</main>', platform_sections(platform, table, figure) + '</main>')
(ROOT/'index.html').write_text(render_page(html, midterm).replace('><', '>\n<')+'\n')
